content:
if (doc->children != NULL) {
            node = doc->children;
            while ((node != NULL) &&
                   ((node->type != XML_ELEMENT_NODE) ||
                    (node->last == NULL)))
                node = node->next;
            if (node != NULL) {
                nb = xmlValidGetValidElements(node->last, NULL, list, 256);
                if (nb < 0) {
                    fprintf(ERR_STREAM, "could not get valid list of elements\n");
                } else if (nb == 0) {
                    fprintf(ERR_STREAM, "No element can be inserted under root\n");
                } else {
                    fprintf(ERR_STREAM, "%d element types can be inserted under root:\n",
                           nb);
                    for (i = 0;i < nb;i++) {
                         fprintf(ERR_STREAM, "%s\n", (char *) list[i]);
                    }
                }
            }
        }
    }else
#endif /* LIBXML_VALID_ENABLED */
#ifdef LIBXML_READER_ENABLED
    if (walker) {
        walkDoc(doc);
    }
#endif /* LIBXML_READER_ENABLED */
#ifdef LIBXML_OUTPUT_ENABLED
    if (noout == 0) {
        if (compress)
            xmlSetDocCompressMode(doc, 9);

        /*
         * print it.
         */
#ifdef LIBXML_DEBUG_ENABLED
        if (!debug) {
#endif
            if ((timing) && (!repeat)) {
                startTimer();
            }
#ifdef LIBXML_HTML_ENABLED
            if ((html) && (!xmlout)) {
                if (compress) {
                    htmlSaveFile(output ? output : "-", doc);
                }
                else if (encoding != NULL) {
                    if (format == 1) {
                        htmlSaveFileFormat(output ? output : "-", doc, encoding, 1);
                    }
                    else {
                        htmlSaveFileFormat(output ? output : "-", doc, encoding, 0);
                    }
                }
                else if (format == 1) {
                    htmlSaveFileFormat(output ? output : "-", doc, NULL, 1);
                }
                else {
                    FILE *out;
                    if (output == NULL)
                        out = stdout;
                    else {
                        out = fopen(output,"wb");
                    }
                    if (out != NULL) {
                        if (htmlDocDump(out, doc) < 0)
                            progresult = XMLLINT_ERR_OUT;

                        if (output != NULL)
                            fclose(out);
                    } else {
                        fprintf(ERR_STREAM, "failed to open %s\n", output);
                        progresult = XMLLINT_ERR_OUT;
                    }
                }
                if ((timing) && (!repeat)) {
                    endTimer("Saving");
                }
            } else
#endif
